INSERT IGNORE INTO content_pages (slug,title,eyebrow,summary,content) VALUES
('ana-sayfa-hakkinda','Vakfımız Hakkında','Ana Sayfa','Karabük Eflani Hayır Vakfı, Eflani ilçemizin sosyal, kültürel ve ekonomik kalkınmasına destek olmak; yardımlaşma ve dayanışma bilincini gelecek nesillere aktarmak amacıyla kurulmuştur.','Kurulduğumuz ilk günden bu yana, hayırseverlerimizin destekleriyle öğrencilerimize eğitim bursu sağlıyor, ihtiyaç sahibi ailelerimizin yanında oluyor ve ilçemizin kültürel mirasını koruyacak projeler yürütüyoruz.\n\nBiz, paylaştıkça çoğalan bir iyilik hareketiyiz. Tüm faaliyetlerimizi şeffaflık ve hesap verebilirlik ilkesiyle sürdürüyoruz.');
